import './App.css';
import { useState } from 'react';
import Dashboard from './dashboard';
import Login from './login';
import Register from './register';

function App() {
  const [showRegister, setShowRegister] = useState(false);
  const [savedUser] = useState(() => {
    const savedSession = localStorage.getItem('taskManagerSession');
    return savedSession ? JSON.parse(savedSession) : null;
  });
  const [isLoggedIn, setIsLoggedIn] = useState(Boolean(savedUser));
  const [userName, setUserName] = useState(savedUser?.userName || 'there');
  const [userRole, setUserRole] = useState(savedUser?.userRole || 'User');

  function handleLogin(name = 'there', role = 'User', rememberMe = false) {
    setUserName(name);
    setUserRole(role);
    setIsLoggedIn(true);

    if (rememberMe) {
      localStorage.setItem('taskManagerSession', JSON.stringify({ userName: name, userRole: role }));
    } else {
      localStorage.removeItem('taskManagerSession');
    }
  }

  function handleLogout() {
    localStorage.removeItem('taskManagerSession');
    setIsLoggedIn(false);
  }

  if (isLoggedIn) {
    return <Dashboard userName={userName} userRole={userRole} onLogout={handleLogout} />;
  }

  return (
    showRegister
      ? <Register onLogin={() => setShowRegister(false)} onSuccess={handleLogin} />
      : <Login onRegister={() => setShowRegister(true)} onSuccess={handleLogin} />
  );
}

export default App;
